package cn.zhuatech.iot.controller; import cn.zhuatech.iot.common.ApiResponse; import cn.zhuatech.iot.dto.IotDto.*; import cn.zhuatech.iot.service.IotService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('FIELD_ENGINEER','ADMIN')") public class FieldOpsController {private final IotService iot;public FieldOpsController(IotService iot){this.iot=iot;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(iot.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",iot.report(id,request));}}
